// ***************
// Filename: intc_regs.h
// Author: FPGA Cores 4 U
// Description: C header of the intc register map (generated by regmap_gen.py): byte offsets, reset values,
//   field shifts and masks.
// Date: 2026-10-16
#ifndef INTC_REGS_H
#define INTC_REGS_H
#define INTC_REGS_ID_OFFSET 0x00u
#define INTC_REGS_VERSION_OFFSET 0x04u
#define INTC_REGS_DATE_OFFSET 0x08u
#define INTC_REGS_ID_VALUE 0x494E5443u   /* "INTC" */
#define INTC_REGS_ENABLE_OFFSET 0x10u   /* RW */
#define INTC_REGS_ENABLE_RESET 0x00000000u
#define INTC_REGS_EDGE_TYPE_OFFSET 0x14u   /* RW */
#define INTC_REGS_EDGE_TYPE_RESET 0x00000000u
#define INTC_REGS_ACTIVE_LOW_OFFSET 0x18u   /* RW */
#define INTC_REGS_ACTIVE_LOW_RESET 0x00000000u
#define INTC_REGS_PENDING_OFFSET 0x1Cu   /* CMD */
#define INTC_REGS_PENDING_RESET 0x00000000u
#define INTC_REGS_SOFT_SET_OFFSET 0x20u   /* WO */
#define INTC_REGS_SOFT_SET_RESET 0x00000000u
#define INTC_REGS_VECTOR_OFFSET 0x24u   /* RO */
#define INTC_REGS_VECTOR_RESET 0x00000000u
#define INTC_REGS_VECTOR_ID_SHIFT 0u
#define INTC_REGS_VECTOR_ID_MASK 0x0000001Fu
#define INTC_REGS_VECTOR_VALID_SHIFT 31u
#define INTC_REGS_VECTOR_VALID_MASK 0x80000000u
#define INTC_REGS_MASKED_OFFSET 0x28u   /* RO */
#define INTC_REGS_MASKED_RESET 0x00000000u
#endif /* INTC_REGS_H */
